inputs.manifest:
{
  "schema_version": "1.0.0",
  "id": "ideogram/t2i",
  "label": {
    "en": "Generate",
    "ru": "Генерация"
  },
  "family": "ideogram",
  "family_label": "Ideogram 4",
  "mode": "t2i",
  "order": 15,
  "controls": [
    {
      "param": "prompt",
      "kind": "prompt",
      "superprompt": true
    },
    {
      "param": "design_json",
      "kind": "designer",
      "provider": "ideogram",
      "label": {
        "en": "Layout",
        "ru": "Макет"
      }
    },
    {
      "param": "seed",
      "kind": "seed"
    },
    {
      "param": "loras",
      "kind": "loras",
      "max": 8,
      "strength": [
        -2.0,
        2.0
      ]
    },
    {
      "param": "steps",
      "kind": "number",
      "advanced": true,
      "min": 1,
      "max": 60,
      "label": {
        "en": "Steps",
        "ru": "Шаги"
      },
      "default": 12
    },
    {
      "param": "cfg",
      "kind": "number",
      "advanced": true,
      "min": 0,
      "max": 15,
      "step": 0.1,
      "label": {
        "en": "CFG",
        "ru": "CFG"
      }
    }
  ],
  "refs": {
    "max": 0
  },
  "negative_prompt": false,
  "models": [
    {
      "title": "studio:model",
      "input": "unet_name",
      "folder": "diffusion_models",
      "match": "ideogram4_(fp8|int8)(?!.*uncond)"
    },
    {
      "title": "studio:model_uncond",
      "input": "unet_name",
      "folder": "diffusion_models",
      "match": "ideogram4_unconditional"
    },
    {
      "title": "studio:clip",
      "input": "clip_name",
      "folder": "text_encoders",
      "match": "qwen3vl_8b"
    },
    {
      "title": "studio:vae",
      "input": "vae_name",
      "folder": "vae",
      "match": "flux2.*flux2-vae-v2"
    }
  ],
  "designer": {
    "param": "design_json",
    "mode_param": "mode",
    "caption_param": "auto_caption",
    "preset": "Ideogram Prompt Enhance"
  },
  "literals": {
    "mode": {
      "node": "designer",
      "input": "mode"
    }
  },
  "prompt_source": {
    "node": "designer",
    "slot": 0
  }
}
